// src/api/customers.js
import apiClient from './api'; // Your configured axios instance

export const fetchCustomers = async () => {
  try {
    const response = await apiClient.get('/customers');
    return response.data.data; // Assuming response has { success: true, data: [...] }
  } catch (error) {
    console.error("Error fetching customers:", error.response?.data?.message || error.message);
    throw error; // Re-throw to be caught by the component
  }
};

export const addCustomer = async (customerData) => {
  try {
    const response = await apiClient.post('/customers', customerData);
    return response.data.data; // Newly created customer
  } catch (error) {
    console.error("Error adding customer:", error.response?.data?.message || error.message);
    throw error;
  }
};

// You might need other functions like getCustomerById, updateCustomer, deleteCustomer
